    private function miningFaqs(): array
    {
        return [
            $this->faq('Does mining software grant or manage the legal validity of a licence?', 'No. The responsible government authority and legal owners determine licence validity. The system references authorized rights, terms, obligations, documents and changes for operational control.', 'آیا mining software اعتبار قانونی licence را تعیین می‌کند؟', 'خیر. authority دولتی و مسئول legal اعتبار licence را تعیین می‌کنند. سیستم حق، term، obligation، document و change مجاز را برای operational control reference می‌کند.', 'ایا mining software د licence قانوني اعتبار ټاکي؟', 'نه. دولتي authority او legal مسؤل د licence اعتبار ټاکي. سیسټم د operational control لپاره مجاز حق، term، obligation، document او change reference کوي.'),
            $this->faq('Can production, stockpiles and dispatch be reconciled?', 'Yes. Approved measurements can connect extraction, processing, recovery, waste, stockpiles, weighbridge, dispatch and sales, with visible differences and review history.', 'آیا production، stockpile و dispatch reconcile می‌شود؟', 'بلی. measurement تأییدشده extraction، processing، recovery، waste، stockpile، weighbridge، dispatch و sale را با difference و review history وصل می‌کند.', 'ایا production، stockpile او dispatch reconcile کېږي؟', 'هو. تایید شوی measurement، extraction، processing، recovery، waste، stockpile، weighbridge، dispatch او sale له difference او review history سره نښلوي.'),
            $this->faq('Can exploration samples and laboratory results be traced?', 'Sample identifiers, collection, custody, transport, laboratory results, review and approved interpretations can be linked. Qualified professionals remain responsible for sampling and technical conclusions.', 'آیا exploration sample و laboratory result پیگیری می‌شود؟', 'sample identifier، collection، custody، transport، laboratory result، review و interpretation تأییدشده وصل می‌شود. متخصص qualified مسئول sampling و conclusion است.', 'ایا exploration sample او laboratory result تعقیبېږي؟', 'sample identifier، collection، custody، transport، laboratory result، review او تایید شوی interpretation نښلي. qualified متخصص د sampling او conclusion مسؤل دی.'),
            $this->faq('Can the platform control explosives or hazardous materials?', 'Generic inventory is not sufficient. Any such scope requires applicable legal, security, safety and professional controls, qualified ownership and a separately validated design.', 'آیا platform explosive یا hazardous material را کنترول می‌کند؟', 'generic inventory کافی نیست. چنین scope به کنترول legal، security، safety و professional، owner qualified و design جدا validate‌شده نیاز دارد.', 'ایا platform explosive یا hazardous material کنټرولوي؟', 'generic inventory بسنه نه کوي. داسې scope قانوني، security، safety او professional کنټرول، qualified owner او جلا validated design غواړي.'),
            $this->faq('What mining data should be migrated?', 'Active rights and obligations, approved masters, locations, opening stockpiles, assets, balances, open work and selected evidence can be migrated after validation and reconciliation.', 'کدام mining data migrate شود؟', 'active right/obligation، master، location، opening stockpile، asset، balance، open work و evidence انتخابی پس از validation و reconciliation منتقل می‌شود.', 'کوم mining data ولېږدول شي؟', 'active right/obligation، master، location، opening stockpile، asset، balance، open work او ټاکلی evidence له validation او reconciliation وروسته لېږدول کېږي.'),
            $this->faq('How is mining software priced?', 'Pricing depends on licences and sites, commodities, operational depth, assets, users, field connectivity, controls, reporting, integrations, migration, deployment, training and support.', 'قیمت mining software چگونه تعیین می‌شود؟', 'قیمت به licence/site، commodity، operational depth، asset، user، field connectivity، control، report، integration، migration، deployment، training و support وابسته است.', 'د mining software بیه څنګه ټاکل کېږي؟', 'بیه په licence/site، commodity، operational depth، asset، user، field connectivity، control، report، integration، migration، deployment، training او support پورې تړلې ده.'),
        ];
    }

    private function energyFaqs(): array
    {
        return [
            $this->faq('Is utility management software the same as SCADA?', 'No. This enterprise layer manages assets, service, work, metering, billing, collections and finance. SCADA and qualified control systems retain operational monitoring and control responsibilities.', 'آیا utility management software همان SCADA است؟', 'خیر. این enterprise layer، asset، service، work، metering، billing، collection و finance را اداره می‌کند. SCADA مسئول operational monitoring/control می‌ماند.', 'ایا utility management software هماغه SCADA دی؟', 'نه. دا enterprise layer، asset، service، work، metering، billing، collection او finance اداره کوي. SCADA د operational monitoring/control مسؤل پاتې کېږي.'),
            $this->faq('Can smart meters or meter-reading systems be integrated?', 'Yes, after meter and service-point identities, reading quality, timestamps, correction rules, interfaces, security, ownership and error handling are defined and tested.', 'آیا smart meter یا meter-reading system ادغام می‌شود؟', 'بلی، پس از تعریف و test هویت meter/service point، reading quality، timestamp، correction، interface، security، ownership و error handling.', 'ایا smart meter یا meter-reading system ادغامېږي؟', 'هو، د meter/service point هویت، reading quality، timestamp، correction، interface، security، ownership او error handling له تعریف او test وروسته.'),
            $this->faq('Does the system establish tariffs or subsidies?', 'No. Authorized regulatory and utility owners approve current tariffs, subsidies and effective dates. The system applies versioned rules and retains calculations, exceptions and approvals.', 'آیا سیستم tariff یا subsidy را تعیین می‌کند؟', 'خیر. مسئول regulatory/utility، tariff، subsidy و effective date را تأیید می‌کند. سیستم rule version‌شده، calculation، exception و approval را حفظ می‌کند.', 'ایا سیسټم tariff یا subsidy ټاکي؟', 'نه. regulatory/utility مسؤل tariff، subsidy او effective date تاییدوي. سیسټم version شوی rule، calculation، exception او approval ساتي.'),
            $this->faq('Can outages and customer notifications be managed?', 'Outage records can connect affected assets or service points, field updates, restoration and approved communications, while safety and control-room decisions remain with qualified teams.', 'آیا outage و customer notification مدیریت می‌شود؟', 'outage record، asset/service point متأثر، field update، restoration و communication تأییدشده را وصل می‌کند؛ safety/control-room decision نزد تیم qualified می‌ماند.', 'ایا outage او customer notification اداره کېږي؟', 'outage record اغېزمن asset/service point، field update، restoration او تایید شوی communication نښلوي؛ safety/control-room decision له qualified ټیم سره پاتې کېږي.'),
            $this->faq('What utility data should be migrated?', 'Validated customers, service points, meters, approved tariffs, opening balances, unpaid items, assets, maintenance plans and open work can be migrated with signed reconciliation.', 'کدام utility data migrate شود؟', 'customer، service point، meter، tariff، opening balance، unpaid item، asset، maintenance plan و open work validate‌شده با reconciliation امضاشده منتقل می‌شود.', 'کوم utility data ولېږدول شي؟', 'validated customer، service point، meter، tariff، opening balance، unpaid item، asset، maintenance plan او open work له لاسلیک شوي reconciliation سره لېږدول کېږي.'),
            $this->faq('How is energy and utility software priced?', 'Pricing depends on service territories, assets, customers and meters, users, billing rules, field work, integrations, migration, deployment, security, training and support.', 'قیمت energy/utility software چگونه تعیین می‌شود؟', 'قیمت به territory، asset، customer/meter، user، billing rule، field work، integration، migration، deployment، security، training و support وابسته است.', 'د energy/utility software بیه څنګه ټاکل کېږي؟', 'بیه په territory، asset، customer/meter، user، billing rule، field work، integration، migration، deployment، security، training او support پورې تړلې ده.'),
        ];
    }

